INSERT INTO diseases (name, english_name, alt_name, source, description, location, rarity, maps, classname, image, causes, symptoms, treatment, prevention) VALUES
('Brain Prion Disease', 'Brain Prion Disease', NULL, 'diseases', NULL, NULL, NULL, NULL, NULL, '/img/items/gui-iconbacteria.webp', 'Consumption of Steak, Guts or Fat from dead humans', 'Tremors, Uncontrollable Laughter', 'None, besides Cupid''s Bolt. Illness is permanent until the player respawns.', 'Avoid eating human remains.'),
('Cholera', 'Cholera', NULL, 'diseases', NULL, NULL, NULL, NULL, NULL, '/img/items/gui-iconbacteria.webp', 'Drinking from ponds, rivers, and stagnant water; Drinking found water bottles and canteens; Sharing food and water with infected players (including yourself)', 'Vomiting, Blurry Vision, Dehydration, Fever', 'Tetracycline Pills or Multivitamin Pills or Natural Immunity', 'Achieve over 95% Immunity; Drink only from water pumps or springs; Purify dirty water with Chlorine Tablets or by boiling.; Avoid sharing partly consumed food and water with sick survivors'),
('Common Cold', 'Common Cold', NULL, 'diseases', NULL, NULL, NULL, NULL, NULL, '/img/items/gui-iconbacteria.webp', 'Being near infected Survivor; Prolonged Exposure to cold; Sharing food, water or blood with infected survivors', 'Sneezing', 'Tetracycline Pills or Multivitamin Pills or Natural Immunity or increasing body temperature (heat comfort) to neutral or above', 'Achieve over 65% Immunity; Stay warm; Keep 3 meter distance from sick survivors or wear masks/helmets with biological protection; Purify water drank by sick survivors; Avoid sharing partly consumed food, water and blood with sick survivors'),
('Food Poisoning', 'Food Poisoning', NULL, 'diseases', NULL, NULL, NULL, NULL, NULL, '/img/items/iconpoisoned.webp', 'Consumption of Gasoline, burned or rotten food, or Unknown food cans;Drinking with bloody hands (without a water container) ;Eating with bloody hands', 'Water and energy loss through Vomiting, Fatigue (Slower Stamina regen)', 'Charcoal Tablets or waiting for it to clear on its own.', 'Avoid rotten/burned foods; Wash bloody hands before eating/drinking, or wear gloves; Don''t eat unknown food cans; Don''t drink Gasoline'),
('Gas Poisoning', 'Gas Poisoning', NULL, 'diseases', NULL, NULL, NULL, NULL, NULL, '/img/items/iconpoisoned.webp', 'Exposure to a Contaminated Zone without the proper safety equipment', 'Coughing, Vomiting, Bleeding, Unconsciousness, Health Damage', 'PO-X Antidote, or 1-4 IV Blood Bags with blood collected from someone not afflicted with Gas Poisoning themselves', 'Stay away from toxic gas; Wear a full NBC suit along with gas mask & filters'),
('Heat Stroke', 'Heat Stroke', 'Heatstroke', 'diseases', NULL, NULL, NULL, NULL, NULL, '/img/items/statustemp.webp', 'Accumulation of thermal bias due to excessive heat comfort and, under certain conditions, low Hydration', 'Water loss, blurred vision, hot-related symptoms, slower Stamina recovery, faster Stamina depletion, Vomiting, health damage, Unconsciousness', 'Reduce heat comfort level and thermal bias by wetting clothes, washing your head, and standing in shade or indoors', 'Wear clothes with low insulation; Frequently wet your head and clothes at water sources or with containers; Maintain high Hydration'),
('Heavy Metal Poisoning', 'Heavy Metal Poisoning', NULL, 'diseases', NULL, NULL, NULL, NULL, NULL, '/img/items/iconpoisoned.webp', 'Consumption of contaminated snow or unchelated water on Sakhal', 'Dehydration, shivers, temporary hearing loss, blurry vision, pain noises, health damage', 'Chelating Tablets, time (if not stage 3)', 'Drink from Water springs; Use Chelating Tablets before drinking or combine with water container; Use Filtering Bottle'),
('Hemolytic Reaction', 'Hemolytic Reaction', NULL, 'diseases', NULL, NULL, NULL, NULL, NULL, '/img/items/iconblood2-warning-plus.webp', 'Improper Blood Transfusion (wrong blood type)', 'Blood loss, Unconsciousness', 'None. Illness will clear on its own over time, unless the survivor dies from blood loss during it.', 'Ensure blood compatibility'),
('Influenza', 'Influenza', NULL, 'diseases', NULL, NULL, NULL, NULL, NULL, '/img/items/gui-iconbacteria.webp', 'Untreated Common Cold', 'Coughing, Sneezing, Fever and blurry screen', 'Tetracycline Pills or Multivitamin Pills or Natural Immunity or increasing body temperature (heat comfort) to neutral or above', 'Prevent Common Cold from progressing to Influenza'),
('Irritated Eyes', 'Irritated Eyes', 'eye irritation, sand in eyes', 'diseases', 'Condition added with the Badlands expansion (1.30).', NULL, NULL, NULL, NULL, '/img/items/gui-iconbacteria.webp', 'Sand and dust in the eyes during Nasdara sandstorms without eye protection', 'Impaired vision. Does not damage health and does not show the sickness icon', 'Use the Wash Face action at a well, pond or other water source (splashing from a bottle helps only a little)', 'Wear goggles (e.g. Dust Goggles) or other eye protection; a mask alone does not protect the eyes'),
('Pneumonia', 'Pneumonia', NULL, 'diseases', NULL, NULL, NULL, NULL, NULL, '/img/items/gui-iconbacteria.webp', 'Untreated Influenza', 'Coughing, Sneezing, Fever, Stamina loss, gasping for air, Health loss, and blurry vision', 'Tetracycline Pills', 'Prevent Influenza from progressing to Pneumonia'),
('Salmonellosis', 'Salmonellosis', NULL, 'diseases', NULL, NULL, NULL, NULL, NULL, '/img/items/gui-iconbacteria.webp', 'Eating uncooked or rotten meat, fat, or guts; Eating cooked Wolf Steak or Bear Steak; Drinking with bloody hands (i.e. without a water container); Eating with bloody hands; Receiving a blood transfusion from a sick survivor; Consuming food or water from a sick survivor', 'Vomiting, Health Damage, Pain noises, Blurry vision.', 'Charcoal Tablets or Multivitamin Pills or Natural Immunity', 'Cook meat and fat before eating; Wash bloody hands before eating, or wear gloves; Wear gloves when skinning and quartering'),
('Silicosis', 'Silicosis', 'Sillicosis, dust lung', 'diseases', 'Respiratory illness added with the Badlands expansion (1.30). Exact exposure thresholds and timings have not been published by the developers.', NULL, NULL, NULL, NULL, '/img/items/gui-iconbacteria.webp', 'Breathing sand and dust during Nasdara sandstorms without a face covering', 'Coughing during sandstorms; heavy breathing and greatly reduced stamina', 'No medicine cures it. Leave the dust and shelter indoors; it clears over time while your immune system is in good shape (fed, hydrated, healthy)', 'Wear a mask or face covering in sandstorms; shelter in buildings, underground or in a vehicle'),
('Wound Infection', 'Wound Infection', NULL, 'diseases', NULL, NULL, NULL, NULL, NULL, '/img/items/gui-iconbacteria.webp', 'Using non-disinfected items to treat wounds; Letting a bleeding wound heal itself', 'Stage 1; Light screen blur; Light pain sounds; Fatigue Stage 2; Heavy screen blur; Heavy pain sounds; Fever; Health Damage', 'Stage 1; Clean wounds with Disinfectant Spray, Iodine Tincture, or Alcoholic Tincture Stage 2; Tetracycline Pills', 'Disinfect item used to treat wounds; Don''t let wounds heal on their own');
INSERT INTO explosives (name, english_name, alt_name, source, description, location, rarity, maps, classname, image, type, delivery, size, weight, durability, tier) VALUES
('Claymore', 'Claymore', 'ClaymoreMine', 'explosives', 'Directional remote controlled mine. A convenient label reminds the user to point it toward the enemy.', 'Military', 'Very Rare', 'Chernarus, Livonia, Sakhal, Nasdara', 'ClaymoreMine', '/img/items/claymore-1.webp', 'Directional fragmentation AP mine', 'Placed, Trap', '4x3', 3.0, NULL, 'Tier 3-4 / Unique · Very Rare'),
('Improvised Explosive', 'Improvised Explosive', NULL, 'explosives', 'A clever design that combines the desire for destruction with the user''s need for safety.', 'Crafted', NULL, NULL, NULL, '/img/items/improvised-explosive.webp', 'Explosive', NULL, '4x3', 0.012, NULL, NULL),
('Plastic Explosive', 'Plastic Explosive', 'Plastic_Explosive', 'explosives', 'Industrial explosive. Useless on its own, but can be combined with a trigger device to create a powerful explosion.', 'Unique Industrial Zones', 'Unique', 'Chernarus, Livonia, Sakhal, Nasdara', 'Plastic_Explosive', '/img/items/plastic-explosive.webp', 'Explosive', NULL, '3x2', 0.4, NULL, 'Tier 3-4 / Unique · Unique'),
('6-M7 Frag Grenade', '6-M7 Frag Grenade', 'M67Grenade', 'explosives', 'Fragmentation grenade type used by western forces. It is lethal in small radius, but it can cause serious injuries at medium ranges.', 'Military', 'Very Rare', 'Chernarus, Livonia, Sakhal, Nasdara', 'M67Grenade', '/img/items/m67grenade.webp', 'Fragmentation', 'Thrown, Trap', '1x2', 0.397, NULL, 'Tier 3-4 · Very Rare'),
('EGD-5 Frag Grenade', 'EGD-5 Frag Grenade', 'RGD5Grenade', 'explosives', 'Fragmentation grenade type used by eastern forces. It is lethal in small radius, but it can cause serious injuries at medium ranges.', 'Military', 'Common', 'Chernarus, Livonia, Sakhal, Nasdara', 'RGD5Grenade', '/img/items/rgd-5-grenade.webp', 'Fragmentation', 'Thrown, Trap', '1x2', 0.31, NULL, 'Tier 3-4 · Common'),
('Land Mine', 'Land Mine', 'LandMineTrap', 'explosives', 'Anti-personnel mine. Provides a nasty surprise for anybody unlucky enough to step on it.', 'Military', 'Very Rare', 'Chernarus, Livonia, Sakhal, Nasdara', 'LandMineTrap', '/img/items/landmine.webp', 'Fragmentation', 'Trap', '2x2', 1.67, NULL, 'Tier 3-4 · Very Rare'),
('PO-X Vial', 'PO-X Vial', 'Grenade_ChemGas', 'explosives', 'A spherical glass container. It''s apparently designed to crack on impact and release the chemical agent stored inside.', 'Dynamic Contaminated Zones', 'Rare', 'Livonia', 'Grenade_ChemGas', '/img/items/po-x-vial.webp', 'Gas', NULL, '1x1', 0.5, NULL, 'Rare'),
('8-M4 Flashbang', '8-M4 Flashbang', 'FlashGrenade', 'explosives', 'Stun grenade used to temporarily overload senses of the enemy combatant, leaving them disoriented and vulnerable.', 'Military', 'Very Rare', 'Chernarus, Livonia, Sakhal, Nasdara', 'FlashGrenade', '/img/items/m84flashbang.webp', 'Non-lethal', 'Thrown, Trap', '2x2', 0.236, NULL, 'Very Rare'),
('1-M8 Smoke Grenade', '1-M8 Smoke Grenade', 'M18SmokeGrenade_White', 'explosives', 'Smoke grenade used by western forces. Comes in many different colors, it can provide cover or mark positions.', 'Military', 'Uncommon', 'Chernarus, Livonia, Sakhal, Nasdara', 'M18SmokeGrenade_White', '/img/items/m18smokegrenade-purple.webp', 'Smoke', 'Thrown, Trap', '1x2', 1.0, NULL, 'Uncommon'),
('EGD-2 Smoke Grenade', 'EGD-2 Smoke Grenade', 'RDG2SmokeGrenade_White', 'explosives', 'Smoke grenade used by eastern forces. Simple, yet effective at providing cover or marking positions.', 'Military, Police', 'Uncommon', 'Chernarus, Livonia, Sakhal, Nasdara', 'RDG2SmokeGrenade_White', '/img/items/rdg2-smoke-granade-black.webp', 'Smoke', 'Thrown, Trap', '2x2', 1.0, NULL, 'Uncommon');
