-- DayZ Wiki seed data, current for DayZ 1.30 (Badlands).
-- Sources: BohemiaInteractive/DayZ-Central-Economy (spawn maps, loot tiers, class names),
-- dayz.wiki.gg (stats, descriptions; CC BY-SA), official 1.30 patch notes.
-- Load after the app has created its tables:  mysql -u<user> -p <db> < db/seed.sql

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM ammunition;
DELETE FROM armors;
DELETE FROM cars;
DELETE FROM diseases;
DELETE FROM explosives;
DELETE FROM foods;
DELETE FROM medicaments;
DELETE FROM modules;
DELETE FROM weapons;
SET FOREIGN_KEY_CHECKS = 1;










CREATE OR REPLACE VIEW full_text_search AS
SELECT name, english_name, alt_name, type AS section, CONCAT('/weapons/', LOWER(REPLACE(english_name, ' ', '_'))) AS url, description, 'weapons' AS source_table, image, maps FROM weapons
UNION ALL
SELECT name, english_name, alt_name, type AS section, CONCAT('/ammunition/', LOWER(REPLACE(english_name, ' ', '_'))) AS url, description, 'ammunition' AS source_table, image, maps FROM ammunition
UNION ALL
SELECT name, english_name, alt_name, type AS section, CONCAT('/armors/', LOWER(REPLACE(english_name, ' ', '_'))) AS url, description, 'armors' AS source_table, image, maps FROM armors
UNION ALL
SELECT name, english_name, alt_name, type AS section, CONCAT('/foods/', LOWER(REPLACE(english_name, ' ', '_'))) AS url, description, 'foods' AS source_table, image, maps FROM foods
UNION ALL
SELECT name, english_name, alt_name, type AS section, CONCAT('/medication/', LOWER(REPLACE(english_name, ' ', '_'))) AS url, description, 'medicaments' AS source_table, image, maps FROM medicaments
UNION ALL
SELECT name, english_name, alt_name, type AS section, CONCAT('/modules/', LOWER(REPLACE(english_name, ' ', '_'))) AS url, description, 'modules' AS source_table, image, maps FROM modules
UNION ALL
SELECT name, english_name, alt_name, 'Cars' AS section, CONCAT('/cars/', LOWER(REPLACE(english_name, ' ', '_'))) AS url, description, 'cars' AS source_table, image, maps FROM cars
UNION ALL
SELECT name, english_name, alt_name, 'Diseases' AS section, CONCAT('/diseases/', LOWER(REPLACE(english_name, ' ', '_'))) AS url, description, 'diseases' AS source_table, image, maps FROM diseases
UNION ALL
SELECT name, english_name, alt_name, 'Explosives' AS section, CONCAT('/explosives/', LOWER(REPLACE(english_name, ' ', '_'))) AS url, description, 'explosives' AS source_table, image, maps FROM explosives;
